<script lang="ts">
	import { request } from './api';
	import { uiText as t,localeTag } from './i18n';
	let {id}:{id:string}=$props();
	let purchaseDate=$state(''),cost=$state(0),salvage=$state(0),life=$state(36),book=$state<number|null>(null),version=$state(0),busy=$state(false),error=$state('');
	async function load(){try{const result=await request<{purchase_date:string|null;purchase_amount:number|null;salvage_amount:number|null;useful_life_months:number|null;book_value:number|null;version:number}>(`/v1/admin/assets/${id}/valuation`);purchaseDate=result.purchase_date??'';cost=result.purchase_amount??0;salvage=result.salvage_amount??0;life=result.useful_life_months??36;book=result.book_value;version=result.version;}catch(cause){error=cause instanceof Error?cause.message:t('Data tidak dapat dimuat.');}}
	async function save(){busy=true;error='';try{await request(`/v1/admin/assets/${id}/valuation`,{method:'POST',body:JSON.stringify({purchase_date:purchaseDate,purchase_amount:cost,salvage_amount:salvage,useful_life_months:life,version})});await load();}catch(cause){error=cause instanceof Error?cause.message:t('Gagal menyimpan data.');}finally{busy=false;}}
</script>
<details ontoggle={event=>{if(event.currentTarget.open)void load();}}><summary>{t('Nilai dan depresiasi')}</summary>{#if book!==null}<p>{t('Nilai buku')}: {new Intl.NumberFormat(localeTag(),{style:'currency',currency:'IDR'}).format(book)}</p>{/if}<p>{t('Metode garis lurus berdasarkan bulan penuh, dibatasi nilai sisa.')}</p>{#if error}<p role="alert">{error}</p>{/if}<form class="editor-form editor-form--embedded" novalidate onsubmit={event=>{event.preventDefault();void save();}}><label>{t('Tanggal perolehan')}<input type="date" bind:value={purchaseDate} required/></label><label>{t('Harga perolehan (Rp)')}<input type="number" bind:value={cost} min="0" max="999999999999" step="1" required/></label><label>{t('Nilai sisa (Rp)')}<input type="number" bind:value={salvage} min="0" max={cost} step="1" required/></label><label>{t('Masa manfaat (bulan)')}<input type="number" bind:value={life} min="1" max="1200" step="1" required/></label><button disabled={busy}>{t('Simpan')}</button></form></details>
<style>details{margin-top:12px;font-size:12px}summary{font-weight:700;cursor:pointer}form{display:grid;gap:8px;margin-top:12px}p{color:var(--muted)}</style>
